    "bloomrush": { name: "BloomRush", description: "Un juego infinito de match-3 con crecimiento de plantas. Intercambia baldosas de naturaleza, haz crecer plantas en 7 etapas y desbloquea 4 mundos de plantas con mecánicas únicas — todo sin conexión." },
    "wordgrid-odyssey": { name: "WordGrid Odisea", description: "Una aventura infinita de sopa de letras con temas estacionales, casillas ocultas, mini-retos, power-ups y progreso guardado localmente." },
    "puzzle-adventure": { name: "Aventura de Puzle", description: "Un juego de plataformas basado en vectores con 100 niveles, 6 mundos, evolución de mascota, desafíos diarios y capítulos de historia." },
    "deadword": { name: "DeadWord: Reinos de Palabras Locales", description: "Una aventura de puzle de escalera de palabras totalmente sin conexión con 6 reinos, 100 niveles, desafíos diarios, monedas, cosméticos y exportación/importación de progreso local." },
    "pattern-pulse": { name: "Pattern Pulse", description: "Un juego infinito de puzle de completar patrones con 7 familias de patrones, niveles con semilla, estrellas, una tienda solo de estrellas, desafíos diarios y semanales, misiones, niveles de jefe, exportación/importación local y soporte para 4 idiomas — todo sin conexión." },
    "percepta": { name: "PERCEPTA", description: "Un juego de puzle de percepción visual con 25 mundos temáticos, más de 500 niveles, batallas de jefes, desafíos diarios, niveles con semilla, árbol de habilidades, tienda de cosméticos, logros, encuentros míticos y respaldo local — todo sin conexión." },
    "aurelith": { name: "Aurelith: El Reino Verdejante", description: "Un épico juego de plataformas de acción y aventura con 26 reinos, 78 fases, 6 héroes, equipo, poderes, batallas de jefes, logros, modo infinito, desafíos diarios y progreso local — todo sin conexión." },
    "lana": { name: "Lana: La Búsqueda del Hueso Dorado", description: "Acompaña a Lana, la bulldog francés, en una aventura de plataformas por 25 reinos de animales para recuperar el Hueso Dorado — perros y amigos animales desbloqueables, cofres del tesoro, tienda, batallas de jefes, misiones, logros y progreso local — todo sin conexión." },
    "swap-puzzle": { name: "Puzzle de Intercambio", description: "Un juego infinito de puzle de intercambiar piezas. Intercambia piezas para reconstruir imágenes en cientos de niveles con rotaciones, espejos, deslizamientos, piezas bloqueadas, potenciadores, temas de tablero, desafíos diarios y logros — todo sin conexión." },
    "ball-quest": { name: "Aventura de la Bola", description: "Un juego de puzle de física donde giras y mueves barras para guiar bolas que rebotan hasta sus agujeros. Modos infantil y adulto, cientos de niveles generados, estrellas, potenciadores, tienda con cosméticos, desafíos diarios y semanales — todo sin conexión." },
