    "circuit-realms": { name: "Schaltkreis-Reiche", description: "Verbinde Energiequellen mit Kristallen durch Drehen der Pfadsteine. 30 Level, 3 Schwierigkeitsgrade, Scherben-Belohnungen und ein In-Game-Shop — alles offline." },
    "bloomrush": { name: "BloomRush", description: "Ein endloses Match-3-Spiel mit Pflanzenwachstum. Tausche Natur-Steine, lass Pflanzen in 7 Stadien wachsen und schalte 4 Pflanzenwelten mit einzigartigen Mechaniken frei — alles offline." },
    "wordgrid-odyssey": { name: "WordGrid Odyssee", description: "Ein endloses Wortsuch-Abenteuer mit saisonalen Themen, verborgenen Feldern, Mini-Herausforderungen, Power-ups und lokal gespeichertem Fortschritt." },
    "puzzle-adventure": { name: "Puzzle-Abenteuer", description: "Ein vektorbasiertes Plattformspiel mit 100 Leveln, 6 Welten, Maskottchen-Entwicklung, täglichen Herausforderungen und Story-Kapiteln." },
    "deadword": { name: "DeadWord: Lokale Wort-Reiche", description: "Ein vollständig offline-Wortleiter-Puzzle-Abenteuer mit 6 Reichen, 100 Leveln, täglichen Herausforderungen, Münzen, Kosmetika und lokalem Fortschritt-Export/Import." },
    "pattern-pulse": { name: "Pattern Pulse", description: "Ein endloses Muster-Vervollständigung-Puzzle-Spiel mit 7 Muster-Familien, gesetzten Leveln, Sternen, einem Sternen-only-Laden, täglichen und wöchentlichen Herausforderungen, Quests, Boss-Leveln, lokalem Export/Import und 4-Sprachen-Unterstützung — alles offline." },
    "percepta": { name: "PERCEPTA", description: "Ein visuelles Wahrnehmungs-Puzzle-Spiel mit 25 thematischen Welten, über 500 Leveln, Boss-Kämpfen, täglichen Herausforderungen, gesetzten Leveln, einem Fähigkeiten-Baum, Kosmetik-Laden, Errungenschaften, mythischen Begegnungen und lokalem Backup — alles offline." },
    "aurelith": { name: "Aurelith: Das Smaragdkönigreich", description: "Ein episches Action-Adventure-Plattformspiel mit 26 Reichen, 78 Phasen, 6 Helden, Ausrüstung, Kräften, Boss-Kämpfen, Erfolgen, Endlos-Modus, täglichen Herausforderungen und lokalem Fortschritt — alles offline." },
    "lana": { name: "Lana: Die Suche nach dem Goldenen Knochen", description: "Begleite Lana, die Französische Bulldogge, auf einer Plattformer-Quest durch 25 Tierreiche, um den Goldenen Knochen zurückzuholen — freischaltbare Hunde und Tierfreunde, Schatzkisten, ein Laden, Boss-Kämpfe, Missionen, Erfolge und lokaler Fortschritt — alles offline." },
    "swap-puzzle": { name: "Tausch-Puzzle", description: "Ein endloses Bildtausch-Puzzle-Spiel. Tausche Teile, um Bilder über hunderte Level wiederherzustellen — mit Drehungen, Spiegelungen, Schiebeaktionen, blockierten Teilen, Power-ups, Brettthemen, täglichen Herausforderungen und Erfolgen — alles offline." },
    "ball-quest": { name: "Kugel-Quest", description: "Ein Physik-Puzzle-Spiel, bei dem du Balken drehst und bewegst, um springende Bälle in ihre Löcher zu lenken. Kinder- und Erwachsenenmodus, hunderte generierte Level, Sterne, Power-ups, ein Laden mit Kosmetik, tägliche und wöchentliche Herausforderungen — alles offline." },
