  "text-replacer": [
    { q: "Wie viele Ersetzungen werden vorgenommen?", a: "Alle Vorkommen werden ersetzt. Das Tool zeigt die Anzahl der vorgenommenen Ersetzungen, damit du das Ergebnis überprüfen kannst." }
  ],
  "text-encrypt": [
    { q: "Ist die Verschlüsselung sicher?", a: "Das Tool verwendet AES-GCM über die Web Crypto API mit einem aus deinem Passwort abgeleiteten SHA-256-Schlüssel. Dies ist eine branchenübliche symmetrische Verschlüsselung. Verwende trotzdem immer ein starkes Passwort." },
    { q: "Kann ich meinen Text wiederherstellen, wenn ich das Passwort verliere?", a: "Nein. AES-GCM-Verschlüsselung ist ohne das richtige Passwort nicht umkehrbar. Es gibt keine Hintertür und keinen Wiederherstellungsmechanismus." },
    { q: "Werden meine Daten irgendwo gesendet?", a: "Nein. Die gesamte Ver- und Entschlüsselung erfolgt in deinem Browser. Dein Text und dein Passwort verlassen niemals dein Gerät." }
  ],
  "text-obfuscator": [
    { q: "Ist Verschleierung dasselbe wie Verschlüsselung?", a: "Nein. Base64-Verschleierung ist Kodierung, keine Verschlüsselung. Jeder kann sie rückgängig machen. Verwende sie, um Text vor flüchtigem Betrachten zu verbergen, nicht zur Sicherheit." },
    { q: "Verarbeitet es Unicode-Text?", a: "Ja. Das Tool verwendet UTF-8-sichere Kodierung und Dekodierung, sodass Akzentzeichen und Emojis korrekt erhalten bleiben." }
  ],
  "rot13": [
    { q: "Was ist ROT13?", a: "ROT13 ersetzt jeden Buchstaben durch den Buchstaben 13 Positionen weiter im Alphabet. Zweimaliges Anwenden von ROT13 stellt den Originaltext wieder her. Es ist eine einfache Chiffre, keine sichere Verschlüsselung." },
    { q: "Betrifft es Zahlen und Satzzeichen?", a: "Nein. Nur die Buchstaben A-Z und a-z werden rotiert. Zahlen, Satzzeichen und andere Zeichen bleiben unverändert." }
  ],
  "text-reverse": [
    { q: "Was kann ich umkehren?", a: "Du kannst Text nach Zeichen (gesamte Zeichenkette umgekehrt), nach Zeilen (Zeilenreihenfolge umgekehrt) oder nach Wörtern (Wortreihenfolge innerhalb jeder Zeile umgekehrt) umkehren." },
    { q: "Beeinflusst das Umkehren die Formatierung?", a: "Die Zeichenumkehr kehrt alles um, einschließlich Leerzeichen. Die Umkehr nach Zeilen oder Wörtern bewahrt den Inhalt innerhalb jeder Zeile oder jedes Wortes, ändert aber deren Reihenfolge." }
  ],
  "line-numbering": [
    { q: "Werden leere Zeilen nummeriert?", a: "Ja. Jede Zeile, auch leere, erhält eine Nummer, sodass die Zeilenanzahl der Ausgabe mit der Eingabe übereinstimmt." }
  ],
  "text-randomizer": [
    { q: "Was kann ich zufällig anordnen?", a: "Du kannst Zeilen, Wörter oder Zeichen mischen. Die Zeilenmischung ordnet ganze Zeilen neu, die Wortmischung ordnet Wörter im Text neu und die Zeichenmischung verwürfelt alle Zeichen." },
    { q: "Kann ich reproduzierbare Ergebnisse erhalten?", a: "Ja. Gib einen Startwert (Seed) ein, dann erzeugt derselbe Seed immer die gleiche Mischreihenfolge. Lass das Feld leer für jedes Mal zufällige Ergebnisse." }
  ],
  "slug-generator": [
    { q: "Was ist ein Slug und warum brauche ich einen?", a: "Ein Slug ist eine URL-freundliche Version eines Textes: klein geschrieben, mit Leerzeichen durch Bindestriche ersetzt und ohne Sonderzeichen. Slugs machen URLs sauberer, lesbarer und besser für SEO." },
    { q: "Kann ich das Trennzeichen anpassen?", a: "Ja. Du kannst zwischen Bindestrichen, Unterstrichen oder einem benutzerdefinierten Trennzeichen wählen. Das Tool verarbeitet auch Akzentzeichen und fasst mehrere Trennzeichen zu einem zusammen." }
  ],
  "text-sorter": [
    { q: "Wie kann ich meinen Text sortieren?", a: "Du kannst Zeilen alphabetisch (A–Z oder Z–A), nach Länge (kürzeste bis längste oder umgekehrt) sortieren oder die aktuelle Reihenfolge umkehren. Jede Option lässt Leerzeilen an ihrer Stelle, sofern du sie nicht entfernst." }
  ],
  "duplicate-line-remover": [
    { q: "Wie funktioniert das Entfernen von Duplikaten?", a: "Das Tool vergleicht jede Zeile und behält nur das erste Vorkommen jedes Duplikats. Die ursprüngliche Reihenfolge der verbleibenden Zeilen bleibt erhalten." },
    { q: "Kann ich die Ergebnisse sortieren?", a: "Ja. Aktiviere das Sortierkästchen, um die eindeutigen Zeilen nach dem Entfernen der Duplikate alphabetisch zu sortieren. Die Anzeige zeigt, wie viele Duplikate entfernt wurden und wie viele eindeutige Zeilen übrig bleiben." },
    { q: "Wird mein Text gespeichert oder hochgeladen?", a: "Nein. Die gesamte Verarbeitung erfolgt in deinem Browser. Dein Text wird nie an einen Server gesendet oder dort gespeichert." }
  ],
  "inventory-manager": [
    { q: "Wird mein Bestand gespeichert?", a: "Ja. Alle Artikel, Mengen und Werte werden im localStorage deines Browsers gespeichert und bleiben erhalten, wenn du zurückkehrst. Nichts wird an einen Server gesendet." },
    { q: "Kann ich den Gesamtwert meines Bestands verfolgen?", a: "Ja. Jeder Artikel speichert eine Menge und einen Stückpreis, und das Dashboard zeigt den Gesamtwert aller Artikel, damit du deinen Lagerwert auf einen Blick siehst." }
  ],
  "simple-crm": [
    { q: "Sind meine Kontaktdaten privat?", a: "Ja. Alle Kontakte, Notizen und Interaktionen werden lokal im localStorage deines Browsers gespeichert. Es werden keine Daten an einen Server hochgeladen." },
    { q: "Kann ich Interaktionen mit jedem Kontakt verfolgen?", a: "Ja. Du kannst Notizen und Interaktionen zu jedem Kontakt erfassen, sodass du einen fortlaufenden Verlauf von Gesprächen, Terminen und Nachfassaktionen an einem Ort hast." }
  ],
  "client-follow-up-tracker": [
    { q: "Wie werden Nachfassaktionen organisiert?", a: "Jede Nachfassaktion ist einem Kunden und einem Fälligkeitsdatum zugeordnet, sodass du auf einen Blick siehst, was überfällig, heute fällig oder anstehend ist, und nie wieder eine Nachfassaktion verpasst." },
    { q: "Werden meine Nachfass-Daten zwischen Besuchen gespeichert?", a: "Ja. Alle Nachfassaktionen und Kunden werden im localStorage deines Browsers gespeichert und bleiben erhalten, wenn du zur Seite zurückkehrst." }
  ],
  "order-status-tracker": [
    { q: "Welche Auftragsphasen kann ich verfolgen?", a: "Du kannst jede Bestellung durch Phasen wie Ausstehend, In Bearbeitung, Versandt und Zugestellt führen und für jede Phase Notizen hinzufügen, damit du immer weißt, wo eine Bestellung steht." },
    { q: "Werden meine Bestelldaten gespeichert?", a: "Ja. Alle Bestellungen und ihre Status werden im localStorage deines Browsers gespeichert und bleiben verfügbar, wenn du zur Seite zurückkehrst." }
  ],
  "business-expense-tracker": [
    { q: "Wie werden Ausgaben kategorisiert?", a: "Du weist jeder Ausgabe eine Kategorie zu, und das Tool summiert die Ausgaben nach Kategorie, damit du auf einen Blick siehst, wohin dein Geld fließt." },
    { q: "Sind meine Ausgabendaten privat?", a: "Ja. Jeder Ausgabeneintrag wird lokal im localStorage deines Browsers gespeichert. Nichts wird an einen Server hochgeladen oder dort geteilt." }
  ],
  "profit-margin-calculator": [
    { q: "Was ist der Unterschied zwischen Marge und Aufschlag?", a: "Die Marge ist der Gewinn als Prozentsatz des Verkaufspreises, während der Aufschlag der Gewinn als Prozentsatz der Kosten ist. Das Tool berechnet beides, damit du richtig kalkulieren kannst." },
    { q: "Welche Eingaben brauche ich?", a: "Gib deine Kosten und deinen Verkaufspreis (oder Umsatz und Kosten) ein. Das Tool zeigt sofort deinen Bruttogewinn, die Margenprozentzahl und die Aufschlagsprozentzahl." }
  ],
  "chore-chart-generator": [
    { q: "Kann ich Hausarbeiten unterschiedlichen Personen zuweisen?", a: "Ja. Du kannst Familienmitglieder hinzufügen und jeder Person Hausarbeiten für jeden Wochentag zuweisen, damit alle wissen, wofür sie verantwortlich sind." },
    { q: "Wird mein Hausarbeitsplan gespeichert?", a: "Ja. Dein Hausarbeitsplan wird im localStorage deines Browsers gespeichert und bleibt erhalten, wenn du zurückkehrst, sodass du ihn im Laufe der Woche aktualisieren kannst." }
  ],
