function toolString(lang, key, values2 = {}) {
  const template = TOOL_STRINGS[lang][key] ?? TOOL_STRINGS.en[key] ?? key;
  if (typeof template !== "string") return key;
  return template.replace(/\{(\w+)\}/g, (_2, name) => String(values2[name] ?? `{${name}}`));
}
function toolStringArray(lang, key) {
  const val = TOOL_STRINGS[lang][key] ?? TOOL_STRINGS.en[key];
  return Array.isArray(val) ? val : [];
}
function toolObjectArray(lang, key) {
  const val = TOOL_STRINGS[lang][key] ?? TOOL_STRINGS.en[key];
  return Array.isArray(val) ? val : [];
}
