function rng(a){return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const WN=w=>(t('wm_p')[Math.min(Math.floor(w/25),3)]||'')+t('w')[w%25];
const wInfo=n=>{const w=Math.floor((n-1)/50);return{w,theme:w%25,shift:Math.floor(w/25)*47}};
const KL=()=>t('kl');
const EVT=()=>t('ev');
const drd=()=>hash('DRD'+new Date().toISOString().slice(0,10))%5===0;
function MY(x,y){const m=L.mc;if(!m||!m.on||Math.hypot(x-m.x,y-m.y)>L.r*1.5)return false;m.hp--;burst(m.x,m.y,'#fff',16);fx('find',6-m.hp);hap(20);if(m.hp<=0){m.on=0;m.done=1;S.gems=(S.gems|0)+2;S.coins+=50;S.st.myth=(S.st.myth|0)+1;burst(m.x,m.y,'#ffd36b',60);msg(t('m_mythic'));save()}return true}
const PG=['bur:3','bg:3','cur:3','tw:3','out:3','amb:3','hal:2'];
const prTot=()=>Object.values(S.pr).reduce((a,b)=>a+b,0);
function prestige(w,b){if((S.pr[w]|0)>=10){msg(t('m_prestige_max'));return}if(wst(w)<90){msg(t('m_prestige_gold'));return}if(!two(b,t('tap_prestige')))return;
  for(let i=1;i<=50;i++)delete S.stars[w*50+i];S.rk[w]=0;S.pr[w]=(S.pr[w]|0)+1;S.st.pres=(S.st.pres|0)+1;S.gems=(S.gems|0)+3;S.coins+=50*S.pr[w];
  const id=PG[(prTot()-1)%PG.length];let pr=t('m_prestige');if(!S.own[id]){S.own[id]=1;const c=CO.find(c=>c.k===id.split(':')[0]);pr+=t('m_unlocked')+cosName(c.k)+': '+optName(c.i[+id.split(':')[1]][0])}
  save();chk();msg(pr);showMap()}
function PT(x,y){const p=L.pt;if(!p||!p.on||Math.hypot(x-p.x,y-p.y)>L.r*1.3)return false;p.on=0;p.done=1;const g=Math.random()<.35;if(g)S.gems=(S.gems||0)+1;else S.coins+=10;burst(p.x,p.y,'#ff7bd5',40);msg(g?t('m_lucky_g'):t('m_lucky_c'));fx('ach');hap(30);S.st.port=(S.st.port|0)+1;save();return true}
const mt=m=>m.split(' ').map(x=>{const k={dark:'dark',fog:'fog',mirror:'mirror',time:'time',swarm:'swarm',memo:'memo',rhythm:'rhythm'}[x];return k?t('mod')[k]:''}).join('');
const PI=Math.PI;

function build(o){
  const R=rng(hash(o.seed)),n=o.n+25*(o.pr|0),boss=o.mode==='camp'&&o.n%10===0;
  let cnt=Math.min(6+Math.floor(n*1.1),70);if(boss)cnt=Math.min(cnt+20,90);
  const na=Math.min(1+Math.floor(n/8),4+(o.pr|0))+(boss?1:0);
  let kinds=['still','rev','shape','slow','blink','pulse'];if(!S.cb)kinds.push('hue');if(o.pr)kinds.push('size');
  const av=kinds.slice(0,Math.min(kinds.length,2+Math.floor(n/3)));
  const base=R()*360,shift=Math.max(18,34-n*.1);
  const MD=boss?['dark time','fog time','swarm time','mirror time','swarm fog','dark swarm','memo time','rhythm swarm'][Math.floor(R()*8)]:n<3?'':['','','dark','fog','mirror','time','swarm','memo','rhythm'][Math.floor(R()*9)],lay=['grid','hex','spiral'][Math.floor(R()*3)],TV=WD[o.theme%25].v.concat(n>2000?WD[(o.theme+7)%25].v:[]),V0=TV[Math.floor(R()*TV.length)];let V1=TV[Math.floor(R()*TV.length)];if(V1===V0)V1=TV[(TV.indexOf(V0)+1)%TV.length];
  L={o,n:o.n,th:WD[o.theme%25],sh:o.shift||0,t:0,anim:0,mist:0,found:0,na,run:0,over:0,objs:[],fx:[],amb:[],hint:null,bad:null,shake:0,boss,par:(6+cnt*.9+na*4)*(1+.06*sk('mas')),slowT:0,pulse:0,cmb:0,lf:-9,mod:MD,lay,lim:(6+cnt*.9+na*4)*(1.5+.1*sk('mas')),tp:.8+R()*.7,fh:0,sec:n<3?-1:hash(o.seed+'sec')%4,pu:0,cmx:0,memo:MD.includes('memo')?1:0,obs:MD.includes('memo')?6:0,maxm:Math.ceil(cnt/2),fz:0,rh:MD.includes('rhythm')?1:0,tier:n<51?0:n<101?1:n<201?2:n<401?3:n<701?4:n<1001?5:n<2001?6:7};
  const idx=[];while(idx.length<na){const i=Math.floor(R()*cnt);if(!idx.includes(i))idx.push(i)}
  for(let i=0;i<cnt;i++)L.objs.push({h:base+(R()-.5)*12,ph:R()*PI*2,sc:.9+R()*.15,jx:(R()-.5)*.2,jy:(R()-.5)*.2,k:null,f:0,v:V0});
  const cnts={};
  idx.forEach(i=>{const k=MD.includes('rhythm')?'rhy':av[Math.floor(R()*av.length)];L.objs[i].k=k;cnts[k]=(cnts[k]||0)+1;if(k==='hue')L.objs[i].h+=(R()<.5?-1:1)*shift;if(k==='size')L.objs[i].sc*=.78;if(k==='shape')L.objs[i].v=V1;L.objs[i].rk=R()<.5?0:1});
  L.ev=n<4?'':(h=>h<10?'gold':h<13?'treasure':h<18?'portal':h<22?'rainbow':h<24?'jackpot':h<27?'chaos':h<31?'mystery':h<32?'mythic':'')(hash(o.seed+'ev')%100);
  if(L.ev==='chaos'&&MD.includes('rhythm'))L.ev='';
  if(L.ev==='chaos'){L.mod=['swarm fog','dark swarm','fog time','swarm time'][Math.floor(R()*4)];L.memo=0;L.obs=0;L.rh=0;L.tp*=1.4}
  L.my=L.ev==='mystery'?(hash(o.seed+'my')%2?'flawless':'blitz'):'';if(L.my==='blitz'){L.mod=(L.mod+' time').trim();L.lim=L.par*.65}
  L.mc=L.ev==='mythic'?{at:3+R()*5,hp:5}:null;
  let ng=L.ev==='gold'?1:L.ev==='treasure'?3:0;while(ng>0){const i=Math.floor(R()*cnt);if(!L.objs[i].k&&!L.objs[i].g){L.objs[i].g=1;ng--}}
  L.pt=L.ev==='portal'?{at:4+R()*10,fu:R(),fv:R()}:null;
  L.objText=Object.entries(cnts).map(([k,v])=>v+'× '+KL()[k]).join(' · ');
  for(let i=0;i<40;i++)L.amb.push({x:R(),y:R(),s:.5+R()*2,v:.01+R()*.03});
  layout();
}
function layout(){
  if(!L||!W)return;const top=78+ST,ah=H-top-58-SB,aw=W-16,n=L.objs.length;let best=0,bc=1;const hf=L.lay==='hex'?.5:0;
  for(let c=1;c<=n;c++){const rw=Math.ceil(n/c),cs=Math.min(aw/(c+hf),ah/rw);if(cs>best){best=cs;bc=c}}
  const rows=Math.ceil(n/bc);L.r=best*.42;const ox=8+(aw-(bc+hf)*best)/2,oy=top+(ah-rows*best)/2;
  if(L.lay==='spiral'){const d=Math.sqrt(Math.PI*aw*ah/(4*n));L.r=d*.4;const cx=8+aw/2,cy=top+ah/2;L.objs.forEach((o,i)=>{const q=i*2.39996,m=Math.sqrt((i+.5)/n);o.x=cx+Math.cos(q)*m*(aw/2-L.r);o.y=cy+Math.sin(q)*m*(ah/2-L.r)});return}
  L.objs.forEach((o,i)=>{const rw=Math.floor(i/bc);o.x=ox+(i%bc+.5+(rw%2?hf:0)+o.jx)*best;o.y=oy+(rw+.5+o.jy)*best});
}
function resize(){const d=Math.min(devicePixelRatio||1,Q>=2?1:Q>=1?1.5:2);W=cv.clientWidth;H=cv.clientHeight;CR=cv.getBoundingClientRect();const cs=getComputedStyle($('sb'));ST=parseFloat(cs.paddingTop)||0;SB=parseFloat(cs.paddingBottom)||0;cv.width=W*d;cv.height=H*d;ctx.setTransform(d,0,0,d,0,0);layout()}
