const HC={};
function HS(col){let c=HC[col];if(!c){c=HC[col]=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d'),gr=g.createRadialGradient(32,32,4,32,32,32);gr.addColorStop(0,col);gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(0,0,64,64)}return c}
const RK=[['r_bronze',10,20,0],['r_silver',25,40,0],['r_gold',40,80,0],['r_platinum',55,120,1],['r_diamond',70,200,2],['r_master',80,300,3],['r_mythic',90,500,5]],RKCOL=['#cd7f32','#c0c0c0','#ffd700','#7fe0d0','#8fd3ff','#ff8cf0','#ff5f5f'];
