  if(best.k){best.f=1;L.found++;L.cmb=L.anim-L.lf<5?L.cmb+1:1;L.lf=L.anim;S.coins+=1;fx('find',L.cmb);hap(15);L.fl=1;S.st.finds++;S.st.combo=Math.max(S.st.combo,L.cmb);L.cmx=Math.max(L.cmx,L.cmb);burst(best.x,best.y,'#4dff9a');L.fx.push({x:best.x,y:best.y-L.r*.6,vx:0,vy:-1,l:1.5,c:'#ffd36b',t:'+1'});if(L.found>=L.na)win()}
