function jl(){if(S.jmp&&!P.learn.j){P.learn.j=1;psave();setTimeout(()=>toast(t('tip_jmp')),(S.nw&&S.nw.length)?3200:700)}}
function conn(){const n=S.r*S.c,fr=[];for(let p=0;p<n;p++)if(!S.lk.includes(p))fr.push(p);const seen=new Set([fr[0]]),q=[fr[0]];while(q.length){const p=q.pop();[p-S.c,p+S.c,p%S.c?p-1:-1,(p+1)%S.c?p+1:-1].forEach(x=>{if(x>=0&&x<n&&!S.lk.includes(x)&&!seen.has(x)){seen.add(x);q.push(x)}})}return seen.size==fr.length}
function jmpUI(){const b=$('#gj');b.setAttribute('aria-label',tf('a_jmp',{n:S.jmp}));b.setAttribute('aria-pressed',S.jm?'true':'false');b.textContent='🌀 '+S.jmp;b.classList.toggle('hide',!S.jmp);b.classList.toggle('pulse',!!S.jm)}
$('#gj').onclick=()=>{if(S.won||!S.jmp)return;S.jm=!S.jm;sfx(S.jm?'jump':'tap');render();toast(S.jm?t('jmpon'):t('jmpoff'))};
function oriOK(id){const r=S.rot[id]%4,x=S.mir[id]?1:0,y=S.mirv[id]?1:0;return(r==0&&!x&&!y)||(r==2&&x&&y)}
function learn(){const nw=(UC[S.ch]||[]).filter(x=>!P.learn[x]);S.nw=nw;if(nw.length){nw.forEach(x=>P.learn[x]=1);psave();setTimeout(()=>{toast(t('new')+' '+nw.map(x=>t('b_'+x)).join(' · '));sfx('g')},600)}}
function trf(k){if(S.won)return;if(S.sel==null){toast(t('selfirst'));return}const pre=okSet();const id=S.order[S.sel];S.h.push([S.order.slice(),S.rot.slice(),S.mir.slice(),S.mirv.slice()]);if(k=='h')S.mir[id]=S.mir[id]?0:1;else if(k=='v')S.mirv[id]=S.mirv[id]?0:1;else S.rot[id]=(S.rot[id]+(4*S.r==3*S.c?1:2))%4;S.moves++;$('#gm').textContent=S.moves;render();if([...okSet()].some(p=>!pre.has(p)))cele(pre);else{S.cmb=0;sfx('rot')}chk()}
// Gentle curve: grid grows one step every 10 levels; every 5-level cycle mixes normal, challenge, small special and a slightly bigger boss level.
function cfg(n){let i,ch,mv=0;if(n<5){[i,ch]=[[0,'classic'],[1,'classic'],[0,'flip'],[1,'mirror'],[2,'classic']][n]}else{const b=Math.min(9,2+Math.floor((n-5)/10)),k=Math.floor(n/5),p=n%5;i=b;ch='classic';if(p==1)ch=['lock','time','flip','blind'][k%4];else if(p==2){ch=['mirror','shift','rot','flip'][k%4];i=Math.max(0,b-1)}else if(p==3)ch=['classic','mirror','time','mix'][k%4];else if(p==4){ch=['classic','lock','mix','time'][k%4];i=Math.min(9,b+1)}}
let[r,c]=SZ[i];if(ch=='rot')[r,c]=[3,4];if(ch=='shift'){[r,c]=SZ[Math.min(4,2+Math.floor(n/30))];mv=Math.min(12,4+Math.floor(n/8))}return mx({r,c,sc:n<5?60:100,ch,mv},n)}
function play(n){const f=cfg(n);start(art(n),W/H,f.r,f.c,f.sc,n,f.ch,f.mv,f.mu)}
