const D=()=>({coins:50,inv:{fix:2,peek:2,undo:3,fix3:0,jump:2},skin:'classic',owned:['classic'],snd:1,vs:.7,vm:.4,vib:1,fx:1,daily:'',learn:{r:0,h:0,v:0},streak:0,hard:0,ach:[],st:{lv:0,s3:0,rot:0,time:0,hard:0,max:0},best:{},dly:{last:'',streak:0,best:0,total:0,hist:{}}});let P=D();try{Object.assign(P,JSON.parse(ld('sp_save')||'{}'))}catch(e){}
