const APP={v:'1.1.0',url:''};   // url: your public game address. It is added to shared results ('' = no link).
let DAILY=null;
// one puzzle per weekday: gentle early in the week, with a twist on Fri/Sat/Sun
const DW=[{r:4,c:5,ch:'classic',mu:[{k:'spin',f:.2,iv:4}]},{r:3,c:3,ch:'classic'},{r:3,c:4,ch:'lock'},{r:4,c:4,ch:'time'},{r:4,c:4,ch:'blind'},{r:4,c:4,ch:'classic',mu:[{k:'dark',m:'some',f:.25,dur:3,cyc:14}]},{r:4,c:5,ch:'classic',mu:[{k:'block',c:2,warn:2,dur:6,cyc:16}]}];
// Fisher-Yates shuffle (same result in every browser when Math.random is seeded, unlike sort(()=>random))
function shuf(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function seeded(d,fn){if(!d)return fn();if(S)S.rn=rng(d.seed*7919+13);const o=Math.random;Math.random=rng(d.seed);try{return fn()}finally{Math.random=o}}
function dKey(){return new Date().toLocaleDateString('en-CA')}
function dPrev(k){const[y,m,d]=k.split('-').map(Number);return new Date(Date.UTC(y,m-1,d)-864e5).toISOString().slice(0,10)}
function dInfo(k){const[y,m,d]=k.split('-').map(Number),u=Date.UTC(y,m-1,d),n=Math.floor(u/864e5)-Math.floor(Date.UTC(2026,0,1)/864e5)+1,w=DW[new Date(u).getUTCDay()];return{k,n,seed:(Math.imul(n,2654435761)>>>0)||1,r:w.r,c:w.c,ch:w.ch,mu:(w.mu||[]).map(x=>({...x}))}}
function dStreak(){const k=dKey(),l=P.dly.last;return l==k||l==dPrev(k)?P.dly.streak:0}
function playDaily(){const i=dInfo(dKey());DAILY={k:i.k,seed:i.seed,n:i.n};start(art(1000000+Math.max(0,i.n)),W/H,i.r,i.c,100,null,i.ch,6,i.mu)}
function dailyCh(){const b=$('#dch');if(!b)return;const k=dKey(),i=dInfo(k),Y=P.dly,st=dStreak(),h=Y.last==k&&Y.hist[k];
 const info=i.r+'×'+i.c+(i.ch!='classic'?' · '+t('ch_'+i.ch):'')+i.mu.map(m=>' · '+MI[m.k]+' '+t('mu_'+m.k)).join('');
 b.innerHTML=h?'<b>✓ '+lgE(t('dc_doneb'))+'</b><small>'+'⭐'.repeat(h.s)+' · '+fmt(h.t)+' · '+lgE(tf('dc_streak',{n:st}))+' · '+lgE(t('dc_replay'))+'</small>'
  :'<b>📅 '+lgE(t('dc'))+'</b><small>'+lgE(info)+(st?' · '+lgE(tf('dc_streak',{n:st})):'')+'</small>';
 b.onclick=playDaily}
function dailyWin(s,st){if(!S.dy)return;const Y=P.dly,k=S.dy.k,had=!!Y.hist[k],first=!had&&k===dKey();let msg;
 if(!had)Y.hist[k]={t:s,m:S.moves,s:st};else{const h=Y.hist[k];if(s<h.t)h.t=s;if(S.moves<h.m)h.m=S.moves;if(st>h.s)h.s=st}
 if(first){Y.streak=Y.last===dPrev(k)?Y.streak+1:1;Y.last=k;Y.total++;Y.best=Math.max(Y.best,Y.streak);const rw=40+Math.min(Y.streak,7)*10+st*5;P.coins+=rw;if(Y.streak%7==0)P.inv.fix3=(P.inv.fix3||0)+1;
  const ks=Object.keys(Y.hist).sort();while(ks.length>60)delete Y.hist[ks.shift()];ach();msg='<br>'+lgE(tf('dc_streak',{n:Y.streak}))+' · +'+rw+' 🪙'}
 else msg='<br>'+lgE(t('dc_again'));
 psave();coins();$('#wstats').innerHTML+=msg;dailyCh()}
