cx.lineWidth=18*(k?1.35:1);cx.strokeStyle=glow?'#fff':'#0004';cx.beginPath();cx.moveTo(b.x-dx,b.y-dy+3);cx.lineTo(b.x+dx,b.y+dy+3);cx.stroke();
