const RULES=[['^Owned: (\\\\d+)$','Tem: $1','Tienes: $1','Besitz: $1'],['^Bought (.+)!$','$1 comprado!','¡$1 comprado!','$1 gekauft!'],['^Weekly challenge (\\\\d)/3$','Desafio semanal $1/3','Desafío semanal $1/3','Wochenaufgabe $1/3'],['^Weekly (\\\\d)/3$','Semanal $1/3','Semanal $1/3','Woche $1/3'],['^Weekly puzzle (\\\\d)/3 done$','Quebra-cabeça semanal $1/3 concluído','Puzle semanal $1/3 completado','Wochenrätsel $1/3 geschafft'],['^Level (\\\\d+)$','Nível $1','Nivel $1','Level $1'],['^Next: level (\\\\d+)$','Próximo: nível $1','Siguiente: nivel $1','Weiter: Level $1'],['^Need (\\\\d+) more coins \\u2014 solve levels to earn them!$','Faltam $1 moedas \\u2014 resolva níveis para ganhar!','Faltan $1 monedas \\u2014 ¡resuelve niveles para ganar!','Noch $1 Münzen \\u2014 löse Level, um sie zu verdienen!'],['^Tap again to buy (.+) for (\\\\d+) coins$','Toque de novo para comprar $1 por $2 moedas','Toca de nuevo para comprar $1 por $2 monedas','Tippe erneut, um $1 für $2 Münzen zu kaufen'],['^Unlocked (.+)!$','$1 desbloqueado!','¡$1 desbloqueado!','$1 freigeschaltet!'],['^(.+) equipped$','$1 equipado','$1 equipado','$1 ausgerüstet'],['^(Goal: .+) \\\\((\\\\d+) taps\\\\)$','$1 ($2 toques)','$1 ($2 toques)','$1 ($2 Züge)'],['^Complete (\\\\d+) levels$','Complete $1 níveis','Completa $1 niveles','Schließe $1 Level ab'],['^Complete (\\\\d+) daily challenges$','Complete $1 desafios diários','Completa $1 desafíos diarios','Schließe $1 Tagesaufgaben ab'],['^Levels (\\\\d+)$','Níveis $1','Niveles $1','Level $1'],['^Stars (\\\\d+)$','Estrelas $1','Estrellas $1','Sterne $1'],['^Best streak (\\\\d+)$','Melhor sequência $1','Mejor racha $1','Beste Serie $1'],['^Dailies (\\\\d+)$','Diários $1','Diarios $1','Tägliche $1'],['^Prestige (\\\\d+)$','Prestígio $1','Prestigio $1','Prestige $1'],['^(\\\\d+) levels: (.+)$','$1 níveis: $2','$1 niveles: $2','$1 Level: $2'],['^(\\\\d+) coins \\\\+ free (.+) board theme$','$1 moedas + tema $2 grátis','$1 monedas + tema $2 gratis','$1 Münzen + Design $2 gratis'],['^Event reward \\\\+(\\\\d+) coins$','Recompensa do evento +$1 moedas','Recompensa del evento +$1 monedas','Event-Belohnung +$1 Münzen'],['^Event complete! (.+) theme unlocked$','Evento completo! Tema $1 desbloqueado','¡Evento completo! Tema $1 desbloqueado','Event geschafft! Design $1 freigeschaltet'],['^Replace your current progress with this save\\\\? \\\\(Kids level (\\\\d+), Adult level (\\\\d+), (\\\\d+) coins\\\\)$','Substituir seu progresso atual por este save? (Nível Criança $1, Nível Adulto $2, $3 moedas)','¿Reemplazar tu progreso actual con esta partida? (Nivel Niños $1, Nivel Adultos $2, $3 monedas)','Aktuellen Fortschritt durch diesen Spielstand ersetzen? (Kinder-Level $1, Erwachsenen-Level $2, $3 Münzen)'],['^Import rejected: (.+)\\\\.$','Importação recusada: $1.','Importación rechazada: $1.','Import abgelehnt: $1.'],['^(.+) \\\\+(\\\\d+)$','$1 +$2','$1 +$2','$1 +$2']];
let LG='en',TM={},RR=[];const LGI={pt:1,es:2,de:3};
function tr(s){if(LG==='en'||!s.trim())return s;if(TM[s])return TM[s];for(const[r,v]of RR)if(r.test(s))return s.replace(r,(...a)=>v.replace(/\\$(\\d)/g,(_,k)=>tr(a[k])));const p=s.split(/(\\s+\\u2022\\s+|\\s{2,}|\\n)/);if(p.length>1)return p.map((x,i)=>i%2?x:tr(x)).join('');const m=s.match(/^([^A-Za-z\\u00C0-\\u024F]+)([\\s\\S]+)$/);return m?m[1]+tr(m[2]):s}
function tx(n){if(n.__o===undefined)n.__o=n.nodeValue;const m=n.__o.match(/^(\\s*)([\\s\\S]*?)(\\s*)$/),v=m[1]+tr(m[2])+m[3];if(v!==n.nodeValue)n.nodeValue=v}
function walk(r){if(r.nodeType===3)return tx(r);const w=document.createTreeWalker(r,4,{acceptNode:n=>/^(SCRIPT|STYLE)$/.test(n.parentNode.tagName)?2:1});let n;while(n=w.nextNode())tx(n)}
function setLang(l){LG=l;const i=LGI[l];TM={};RR=[];if(i){for(const r of DICT)TM[r[0]]=r[i];for(const r of RULES)RR.push([new RegExp(r[0]),r[i]])}S.lang=l;save();document.documentElement.lang=l;$('lg').value=l;$('dt').placeholder=tr('Or paste a save code here');walk(document.body)}
function startI18n(){const d=(navigator.language||'en').toLowerCase().slice(0,2);setLang(S.lang||(LGI[d]?d:'en'));new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')tx(m.target);else m.addedNodes.forEach(walk)}}).observe(document.body,{childList:true,characterData:true,subtree:true});$('lg').onchange=e=>setLang(e.target.value)}
function vol(k){const a=S.aud||{m:.8,s:.8,u:.4,x:false};return a.x?0:a.m*a[k]}
let MU=null;
function music(){if(vol('u')<=.001){clearInterval(MU);MU=null;return}if(MU)return;try{AC=AC||new AudioContext()}catch(e){return}let i=0;const N=[0,2,4,7,9,12,9,7,4,2],B=[0,0,5,5,7,7,5,5];MU=setInterval(()=>{try{const v=vol('u');if(v<=.001||AC.state!=='running')return;const f=261.63*Math.pow(2,(N[i%N.length]+B[Math.floor(i/10)%B.length])/12),o=AC.createOscillator(),g=AC.createGain(),t=AC.currentTime;o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07*v,t+.05);g.gain.exponentialRampToValueAtTime(.0001,t+.9);o.connect(g);g.connect(AC.destination);o.start();o.stop(t+1);i++}catch(e){}},420)}
addEventListener('pointerdown',()=>{try{AC=AC||new AudioContext();AC.resume();music()}catch(e){}});
function audUI(){const a=S.aud;$('vm').value=a.m*100;$('vs').value=a.s*100;$('vu').value=a.u*100;$('vx').checked=a.x}
[['vm','m'],['vs','s'],['vu','u']].forEach(([id,k])=>{$(id).oninput=e=>{S.aud[k]=e.target.value/100;save();if(k==='s')beep(600,.06);music()}});
$('vx').onchange=e=>{S.aud.x=e.target.checked;save();music()};
function tone(f,d=.1,ty='sine',v=1,f2){try{AC=AC||new AudioContext();const t=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.type=ty;o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+d);g.gain.setValueAtTime(.14*v*vol('s'),t);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(AC.destination);o.start(t);o.stop(t+d+.02)}catch(e){}}
function noise(d=.1,v=1,fq=1200,ty='bandpass'){try{AC=AC||new AudioContext();const t=AC.currentTime,n=Math.floor(AC.sampleRate*d),b=AC.createBuffer(1,n,AC.sampleRate),c=b.getChannelData(0);for(let i=0;i<n;i++)c[i]=(Math.random()*2-1)*(1-i/n);const s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();s.buffer=b;f.type=ty;f.frequency.value=fq;g.gain.value=.3*v*vol('s');s.connect(f);f.connect(g);g.connect(AC.destination);s.start(t)}catch(e){}}
const seq=(a,d,fn)=>a.forEach((f,i)=>setTimeout(()=>fn(f),i*d));
const SFX={click:()=>tone(900,.05,'triangle',.5),bar:k=>{tone(320+k*55,.07,'square',.3,160+k*25);noise(.04,.5,2500,'highpass')},release:()=>{noise(.45,.7,700);tone(200,.4,'sawtooth',.25,700)},bounce:v=>{const q=Math.min(1,v/500);tone(190+Math.random()*30,.1,'sine',q,70);noise(.04,q*.7,1800)},boing:()=>{tone(170,.32,'sine',1,640);setTimeout(()=>tone(640,.16,'sine',.5,330),120)},roll:v=>noise(.09,Math.min(.4,v/500),320,'lowpass'),star:()=>seq([1047,1319,1568],60,f=>tone(f,.16,'triangle',.7)),hole:c=>{tone(280,.2,'sine',1,110);setTimeout(()=>tone([523,659,784][c]||523,.35,'triangle',.8),90)},sw:()=>{tone(700,.05,'square',.45);setTimeout(()=>tone(1000,.08,'square',.45),60)},gate:()=>{noise(.5,.6,400,'lowpass');tone(110,.5,'sawtooth',.35,230)},tp:()=>{tone(1300,.3,'sine',.6,300);setTimeout(()=>tone(300,.3,'sine',.6,1300),130);noise(.3,.3,2000,'highpass')},fail:()=>seq([330,277,220],150,f=>tone(f,.24,'sawtooth',.45)),err:()=>tone(180,.2,'square',.4),win:()=>seq([523,659,784,1047,1319],110,f=>tone(f,.32,'triangle',.8)),buy:()=>{tone(1568,.1,'square',.4);setTimeout(()=>tone(2093,.35,'square',.4),90)},ach:()=>seq([784,988,1175,1568],130,f=>tone(f,.42,'triangle',.8))};
addEventListener('pointerdown',e=>{if(e.target.closest&&e.target.closest('button'))SFX.click()});
let paused=false,weekly=0;
function weekKey(){const d=new Date(),m=new Date(d.getFullYear(),d.getMonth(),d.getDate()-(d.getDay()+6)%7);return m.getFullYear()*10000+(m.getMonth()+1)*100+m.getDate()}
function wkState(){if(!S.weekly||S.weekly.k!==weekKey())S.weekly={k:weekKey(),n:0,done:0};return S.weekly}
function mkWeekly(i){const k=weekKey();DSEED=k+i*977;let l=null;try{l=gen((mode?30:18)+i*4+k%7,mode)}finally{DSEED=0}return l||gen(S.lv[mode],mode)}
function wkWin(){const w=wkState();w.n++;if(w.n>=3&&!w.done){w.done=1;S.coins+=75;S.xp+=40;S.st.weekly=(S.st.weekly||0)+1}}
function pause(on){paused=on;$('pz').classList.toggle('on',on);$('psl').textContent=S.aud.x?'Sound: Off':'Sound: On'}
$('pr').onclick=()=>pause(false);
$('pt').onclick=()=>{pause(false);reset()};
$('ps').onclick=()=>{S.aud.x=!S.aud.x;save();music();$('psl').textContent=S.aud.x?'Sound: Off':'Sound: On'};
$('pm').onclick=()=>{pause(false);daily=0;weekly=0;goMenu()};
$('mw').onclick=()=>{if(wkState().done)return;start(S.lastMode||0,0,1)};
addEventListener('keydown',e=>{if(e.key==='Escape'&&$('game').classList.contains('on')&&!$('win').classList.contains('on'))pause(!paused)});
