g.fillStyle='#1b2236';g.beginPath();g.arc(x,y+s*.22,s*.1,0,7);g.fill();g.strokeStyle='#1b2236';g.lineWidth=s/16;g.beginPath();g.arc(x,y+s*.3,s*.2,.2,2.9);g.stroke();
if(a==='hat'){g.fillStyle='#5b3fc4';g.beginPath();g.moveTo(x-s*.9,y-s*.55);g.lineTo(x,y-s*1.9);g.lineTo(x+s*.9,y-s*.55);g.closePath();g.fill();g.fillRect(x-s*1.15,y-s*.62,s*2.3,s*.2);g.fillStyle='#ffd23a';g.beginPath();g.arc(x,y-s*1.1,s*.12,0,7);g.fill()}
