function normalize(s2) {
  return s2.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}
function levenshtein(a2, b2) {
  const m2 = a2.length;
  const n2 = b2.length;
  if (m2 === 0) return n2;
  if (n2 === 0) return m2;
  const dp = Array.from({ length: m2 + 1 }, () => new Array(n2 + 1).fill(0));
  for (let i2 = 0; i2 <= m2; i2++) dp[i2][0] = i2;
  for (let j2 = 0; j2 <= n2; j2++) dp[0][j2] = j2;
  for (let i2 = 1; i2 <= m2; i2++) {
    for (let j2 = 1; j2 <= n2; j2++) {
      const cost = a2[i2 - 1] === b2[j2 - 1] ? 0 : 1;
      dp[i2][j2] = Math.min(dp[i2 - 1][j2] + 1, dp[i2][j2 - 1] + 1, dp[i2 - 1][j2 - 1] + cost);
    }
  }
  return dp[m2][n2];
}
function dailyIndex(count, salt) {
  const dayNum = Math.floor(Date.now() / 864e5);
  const cycle = Math.floor((dayNum + salt) / count);
  const indexInCycle = (dayNum + salt) % count;
  let a2 = cycle * 1e3 + salt >>> 0;
  const rng2 = () => {
    a2 = a2 + 1831565813 >>> 0;
    let t3 = a2;
    t3 = Math.imul(t3 ^ t3 >>> 15, t3 | 1);
    t3 ^= t3 + Math.imul(t3 ^ t3 >>> 7, t3 | 61);
    return ((t3 ^ t3 >>> 14) >>> 0) / 4294967296;
  };
  const indices = Array.from({ length: count }, (_2, i2) => i2);
  for (let i2 = count - 1; i2 > 0; i2--) {
    const j2 = Math.floor(rng2() * (i2 + 1));
    [indices[i2], indices[j2]] = [indices[j2], indices[i2]];
  }
  return indices[indexInCycle];
}
