const WYR_PARTS = { en: wyrEn, pt: wyrPt, es: wyrEs, de: wyrDe };
const WYR_SPACE = wyrEn.options.length * (wyrEn.options.length - 1);
function generateWouldYouRatherByIndex(lang, index2) {
  const p2 = WYR_PARTS[lang] || WYR_PARTS.en;
  const n2 = p2.options.length;
  const i2 = (index2 % WYR_SPACE + WYR_SPACE) % WYR_SPACE;
  const indexA = Math.floor(i2 / (n2 - 1));
  let indexB = i2 % (n2 - 1);
  if (indexB >= indexA) indexB += 1;
  const optionA = p2.options[indexA];
  const optionB = p2.options[indexB];
  return lang === "en" ? `Would you rather ${optionA} or ${optionB}?` : lang === "pt" ? `Você preferiria ${optionA} ou ${optionB}?` : lang === "es" ? `¿Preferirías ${optionA} o ${optionB}?` : `Würdest du lieber ${optionA} oder ${optionB}?`;
}
function getDailyWouldYouRather(lang, dayIndex) {
  return generateWouldYouRatherByIndex(lang, dailyCombinatorial(WYR_SPACE, dayIndex, 1));
}
